/// Reads a call off the wire and hands it to the plugin; a malformed call never reaches it.
final class ARGlue: WireServiceInstance {
    private let plugin: ARPlugin
    /// The host's permission service: what a method tagged `@permission` is gated by.
    private let permissions: Permissions

    init(_ plugin: ARPlugin, _ permissions: Permissions) {
        self.plugin = plugin
        self.permissions = permissions
    }

    func call(_ method: String, wire args: WireIn, _ settle: ChannelSettle) {
        switch method {
        case "start":
            let w0 = args[0]
            var a0: StartOptions? = nil
            if w0.isPresent {
                guard let v = StartOptions(wire: w0) else { return settle.reject("bad arguments — AR.start: options") }
                a0 = v
            }
            let reply = Reply<Void, ARCode>(settle)
            permissions.ensure([.camera]) { [plugin] granted in
                guard granted else { return reply.reject(.denied) }
                plugin.start(a0, reply)
            }
        case "stop":
            plugin.stop(Reply<Void, ARCode>(settle))
        case "setImages":
            guard let a0 = args[0].list({ v0 in ImageTarget(wire: v0) }) else { return settle.reject("bad arguments — AR.setImages: images") }
            plugin.setImages(a0, Reply<Void, ARCode>(settle))
        case "setCodes":
            guard let a0 = args[0].list({ v0 in QRTarget(wire: v0) }) else { return settle.reject("bad arguments — AR.setCodes: codes") }
            plugin.setCodes(a0, Reply<Void, ARCode>(settle))
        case "hitTest":
            guard let a0 = args[0].f64 else { return settle.reject("bad arguments — AR.hitTest: x") }
            guard let a1 = args[1].f64 else { return settle.reject("bad arguments — AR.hitTest: y") }
            let w2 = args[2]
            var a2: HitTarget? = nil
            if w2.isPresent {
                guard let v = HitTarget(wire: w2) else { return settle.reject("bad arguments — AR.hitTest: target") }
                a2 = v
            }
            plugin.hitTest(a0, a1, a2, Reply<[HitResult], ARCode>(settle) { v, w in
                w.beginArray(v.count)
                for v1 in v { v1.write(to: w) }
                w.end()
            })
        case "anchor":
            guard let a0 = args[0].entity else { return settle.reject("bad arguments — AR.anchor: entity") }
            guard let a1 = Pose(wire: args[1]) else { return settle.reject("bad arguments — AR.anchor: pose") }
            plugin.anchor(a0, a1, Reply<Void, ARCode>(settle))
        case "release":
            guard let a0 = args[0].entity else { return settle.reject("bad arguments — AR.release: entity") }
            plugin.release(a0, Reply<Void, ARCode>(settle))
        case "captureFrame":
            plugin.captureFrame(Reply<PluginFile, ARCode>(settle) { v, w in v.write(to: w) })
        default:
            settle.reject("Unknown method: \(method)")
        }
    }

    func close() { plugin.close() }
}
